package nl.smartstreamlabs.sbwdroneconfig;
import com.atsuishio.superbwarfare.entity.projectile.SmallCannonShellEntity;
import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.server.level.*;import net.minecraft.world.phys.*;import net.minecraft.nbt.CompoundTag;import java.util.*;
import software.bernie.geckolib.animatable.GeoEntity;import software.bernie.geckolib.animatable.instance.AnimatableInstanceCache;import software.bernie.geckolib.animation.AnimatableManager;import software.bernie.geckolib.util.GeckoLibUtil;
/** Native SBW swept projectile movement/collision with one controlled game homing/fuse step. */
public class Pm01Entity extends SmallCannonShellEntity implements GeoEntity {
 private static final boolean MOVE_HOOK=moveHook();private static boolean moveHook(){try{com.atsuishio.superbwarfare.entity.projectile.FastThrowableProjectile.class.getDeclaredMethod("projectileMove",Level.class);return true;}catch(NoSuchMethodException old){return false;}}
 private static final Map<ServerLevel,Set<UUID>> ACTIVE=new WeakHashMap<>();private final AnimatableInstanceCache cache=GeckoLibUtil.createInstanceCache(this);
 private UUID principal,vehicle,target;private net.minecraft.core.BlockPos installation;private String principalName="";private Vec3 origin=Vec3.ZERO;private int age,lost;private boolean spent;
 public Pm01Entity(EntityType<? extends Pm01Entity> t,Level l){super(t,l);setNoGravity(true);}
 public static int active(ServerLevel l){return ACTIVE.getOrDefault(l,Set.of()).size();}public static void track(ServerLevel l,UUID id,boolean add){var s=ACTIVE.computeIfAbsent(l,k->new HashSet<>());if(add)s.add(id);else s.remove(id);}public static void reset(){ACTIVE.clear();}
 public boolean ignoresInstallation(net.minecraft.core.BlockPos root){return installation!=null&&age<=10&&installation.equals(root);}
 public static int assigned(ServerLevel l,UUID goal){int count=0;for(var id:ACTIVE.getOrDefault(l,Set.of()))if(l.getEntity(id)instanceof Pm01Entity m&&goal.equals(m.targetId()))count++;return count;}
 public UUID principal(){return principal;}public UUID vehicle(){return vehicle;}public String principalName(){return principalName;}public UUID targetId(){return target;}
 public void launch(Mpl01Entity source,ServerPlayer actor,Entity goal,Vec3 at,Vec3 direction){launch((PatriotLauncher)source,actor,goal,at,direction);}
 public void launch(PatriotLauncher source,ServerPlayer actor,Entity goal,Vec3 at,Vec3 direction){principal=source.defenseOwner();principalName=source.defenseOwnerName();vehicle=source.defenseId();installation=source instanceof DefenseBlockEntity block?block.getBlockPos():null;target=goal.getUUID();origin=at;setLife(Mpl01Config.LIFE.get());setDamage(0);setExplosionDamage(0);setExplosionRadius(0);setOwner(actor);moveTo(at.x,at.y,at.z,Mpl01Frames.yaw(direction),Mpl01Frames.pitch(direction));yRotO=getYRot();xRotO=getXRot();setDeltaMovement(direction.scale(Mpl01Config.SPEED.get()));DroneExplosionVfx.markPayload(this);}
 private boolean valid(Entity t){return level()instanceof ServerLevel l&&Mpl01Entity.airDrone(t)&&Adv01Targets.relation(l,principal,principalName,t)==Adv01Targets.HOSTILE&&t.position().distanceToSqr(origin)<=Mpl01Config.RANGE.get()*Mpl01Config.RANGE.get();}
 private boolean step(Level level){if(level.isClientSide)return false;if(spent||isRemoved())return true;var l=(ServerLevel)level;if(++age>Mpl01Config.LIFE.get()||position().distanceToSqr(origin)>Math.pow(Mpl01Config.RANGE.get()*1.5,2)){discard();return true;}var goal=target==null?null:l.getEntity(target);if(!valid(goal)){if(++lost>20){discard();return true;}}else{lost=0;if(age>10){var delta=goal.getBoundingBox().getCenter().subtract(position());var v=goal.getDeltaMovement();double lead=Dil01Lead.time(delta.x,delta.y,delta.z,v.x,v.y,v.z,Mpl01Config.SPEED.get());var desired=goal.getBoundingBox().getCenter().add(v.scale(Math.min(30,lead))).subtract(position()).normalize();Vec3 current=getDeltaMovement().normalize();double angle=Math.acos(Math.max(-1,Math.min(1,current.dot(desired))));double f=angle<1e-6?1:Math.min(1,Math.toRadians(Mpl01Config.TURN.get())/angle);Vec3 direction=current.lerp(desired,f).normalize();if(direction.lengthSqr()<.5)direction=current;setDeltaMovement(direction.scale(Mpl01Config.SPEED.get()));}}
  var movement=getDeltaMovement();if(movement.lengthSqr()<.01){discard();return true;}Vec3 start=position(),end=start.add(movement);if(!Hgd01Lasers.loaded(l,start,end)){discard();return true;}Vec3 forward=movement.normalize(),nose=start.add(forward.scale(2.825)),nextNose=end.add(forward.scale(2.825));if(!Hgd01Lasers.loaded(l,nose,nextNose)){discard();return true;}
  var wall=l.clip(new ClipContext(nose,nextNose,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,this));Vec3 clipped=wall.getType()==HitResult.Type.MISS?nextNose:wall.getLocation();
  if(age>8&&valid(goal)){var c=goal.getBoundingBox().getCenter();double t=Adv01Frames.closestFraction(nose.x,nose.y,nose.z,clipped.x,clipped.y,clipped.z,c.x,c.y,c.z);var at=nose.lerp(clipped,t);if(at.distanceToSqr(c)<=Mpl01Config.FUSE.get()*Mpl01Config.FUSE.get()&&Adv01Targets.clear(l,this,at,c)){burstAgainst(goal,at);return true;}}
  if(wall.getType()!=HitResult.Type.MISS){burst(clipped);return true;}setYRot(Mpl01Frames.yaw(forward));setXRot(Mpl01Frames.pitch(forward));return false;
 }
 @Override public void tick(){if(!MOVE_HOOK&&step(level()))return;super.tick();if(level().isClientSide)Pm01Effects.step(this);}
 
 @Override protected double getDefaultGravity(){return 0;}
 @Override protected boolean canHitEntity(Entity e){if(vehicle!=null&&(vehicle.equals(e.getUUID())||e.getVehicle()!=null&&vehicle.equals(e.getVehicle().getUUID())))return false;if(level()instanceof ServerLevel l&&Adv01Targets.drone(e)&&Adv01Targets.relation(l,principal,principalName,e)!=Adv01Targets.HOSTILE)return false;return super.canHitEntity(e);}
 private void burstAgainst(Entity goal,Vec3 at){if(spent||isRemoved())return;if(goal instanceof Fl01Entity fl&&valid(fl)&&level()instanceof ServerLevel l){var type=l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(com.atsuishio.superbwarfare.init.ModDamageTypes.CUSTOM_EXPLOSION);boolean damaged=((Entity)fl).hurt(new net.minecraft.world.damagesource.DamageSource(type,this,getOwner()),Mpl01Config.DAMAGE.get().floatValue());if(Boolean.getBoolean("fl01.trace"))System.out.println("FL01_INTERCEPT accepted="+damaged+" health="+fl.getHealth()+" removed="+fl.isRemoved());}burst(at);}
 private void hitAircraft(EntityHitResult h){burstAgainst(h.getEntity(),h.getLocation());}
 // Confirmed direct/proximity contact on the long airframe uses the ordinary damage hook; the blast still occurs once at its real contact point.
 @Override public void onHitEntity(EntityHitResult h){hitAircraft(h);}@Override public void onHitBlock(BlockHitResult h){burst(h.getLocation());}public void afterHitEntity(EntityHitResult h){hitAircraft(h);}public void afterHitBlock(BlockHitResult h){burst(h.getLocation());}@Override public void causeExplode(Vec3 at){burst(at);}public void performDamage(Entity e,float damage,boolean headshot){}@Override public void destroyBlock(BlockHitResult h){}
 private void burst(Vec3 at){if(!(level()instanceof ServerLevel l)||spent||isRemoved())return;spent=true;var owner=getOwner();DroneExplosionVfx.markPayload(this);var type=l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(com.atsuishio.superbwarfare.init.ModDamageTypes.PROJECTILE_EXPLOSION);var source=new net.minecraft.world.damagesource.DamageSource(type,this,owner);var explosion=new com.atsuishio.superbwarfare.tools.CustomExplosion.Builder(this).directSource(this).source(this).attacker(owner).position(at).damageSource(source).damage(Mpl01Config.DAMAGE.get().floatValue()).radius(Mpl01Config.RADIUS.get().floatValue()).fireTime(0);if(!Mpl01Config.BLOCK_DAMAGE.get())explosion.keepBlock();explosion.explode();discard();}
 @Override public boolean forceLoadChunk(){return false;}
 @Override public void remove(RemovalReason r){if(level()instanceof ServerLevel l)track(l,getUUID(),false);super.remove(r);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(installation!=null)n.putLong("PmInstallation",installation.asLong());if(principal!=null)n.putUUID("PmOwner",principal);if(vehicle!=null)n.putUUID("PmVehicle",vehicle);if(target!=null)n.putUUID("PmTarget",target);n.putString("PmName",principalName);n.putInt("PmAge",age);n.putInt("PmLost",lost);n.putBoolean("PmSpent",spent);n.putDouble("PmOriginX",origin.x);n.putDouble("PmOriginY",origin.y);n.putDouble("PmOriginZ",origin.z);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);installation=n.contains("PmInstallation")?net.minecraft.core.BlockPos.of(n.getLong("PmInstallation")):null;principal=n.hasUUID("PmOwner")?n.getUUID("PmOwner"):null;vehicle=n.hasUUID("PmVehicle")?n.getUUID("PmVehicle"):null;target=n.hasUUID("PmTarget")?n.getUUID("PmTarget"):null;principalName=n.getString("PmName");age=Math.max(0,n.getInt("PmAge"));lost=Math.max(0,n.getInt("PmLost"));spent=n.getBoolean("PmSpent");origin=new Vec3(n.getDouble("PmOriginX"),n.getDouble("PmOriginY"),n.getDouble("PmOriginZ"));setLife(Mpl01Config.LIFE.get());setNoGravity(true);DroneExplosionVfx.markPayload(this);if(spent)discard();}
 public AnimatableInstanceCache getAnimatableInstanceCache(){return cache;}public void registerControllers(AnimatableManager.ControllerRegistrar c){}
 @Override public AABB getBoundingBoxForCulling(){return getBoundingBox().inflate(3.3);}
}
